var alienOrder = function(words) {
    const adj = new Map();
    const inDegree = new Map();
    for (const w of words) for (const c of w) inDegree.set(c, 0);
    for (let i = 0; i + 1 < words.length; i++) {
        const w1 = words[i], w2 = words[i + 1];
        const len = Math.min(w1.length, w2.length);
        if (w1.length > w2.length && w1.startsWith(w2)) return "";
        for (let j = 0; j < len; j++) {
            if (w1[j] !== w2[j]) {
                if (!adj.has(w1[j])) adj.set(w1[j], new Set());
                if (!adj.get(w1[j]).has(w2[j])) {
                    adj.get(w1[j]).add(w2[j]);
                    inDegree.set(w2[j], inDegree.get(w2[j]) + 1);
                }
                break;
            }
        }
    }
    const queue = [];
    for (const [c, deg] of inDegree.entries()) if (deg === 0) queue.push(c);
    const res = [];
    while (queue.length) {
        const c = queue.shift();
        res.push(c);
        if (adj.has(c)) {
            for (const nxt of adj.get(c)) {
                inDegree.set(nxt, inDegree.get(nxt) - 1);
                if (inDegree.get(nxt) === 0) queue.push(nxt);
            }
        }
    }
    return res.length === inDegree.size ? res.join("") : "";
};
